    assert!(pos.azimuth.abs() < 0.01);
    assert!(pos.elevation.abs() < 0.01);
    assert!((pos.distance - 1.0).abs() < 0.01);

    let pos = SourcePosition::from_cartesian(0.0, 0.0, 1.0);
