#[test]
fn test_to_cartesian_unit_vector_cardinal_directions() {
    let eps = 1e-5;
    let front = SourcePosition::new(0.0, 0.0, 1.0).to_cartesian_unit_vector();
    assert!((front[0] - 1.0).abs() < eps, "front x mismatch");
    assert!(front[1].abs() < eps, "front y mismatch");
    assert!(front[2].abs() < eps, "front z mismatch");

    let left = SourcePosition::new(90.0, 0.0, 2.0).to_cartesian_unit_vector();
    assert!(left[0].abs() < eps, "left x mismatch");
    assert!((left[1] - 1.0).abs() < eps, "left y mismatch");
    assert!(left[2].abs() < eps, "left z mismatch");

    let up = SourcePosition::new(0.0, 90.0, 0.5).to_cartesian_unit_vector();
    assert!(up[0].abs() < eps, "up x mismatch");
    assert!(up[1].abs() < eps, "up y mismatch");
    assert!((up[2] - 1.0).abs() < eps, "up z mismatch");

    let back = SourcePosition::new(180.0, 0.0, 1.0).to_cartesian_unit_vector();
    assert!((back[0] + 1.0).abs() < eps, "back x mismatch");
    assert!(back[1].abs() < eps, "back y mismatch");
    assert!(back[2].abs() < eps, "back z mismatch");
}

