#[test]
fn test_lookup_distance_angular_and_radial() {
    let a = SourcePosition::new(0.0, 0.0, 1.0);
    let b = SourcePosition::new(90.0, 0.0, 2.0);
    let d = SofaFile::lookup_distance(&a, &b);
    let angular = 90.0f32.to_radians();
    let radial = 1.0f32;
    let mean_r = ((a.distance + b.distance) * 0.5).max(1e-3);
    let tangential = mean_r * angular;
    let expected = (tangential * tangential + radial * radial).sqrt();
    assert!(
        (d - expected).abs() < 1e-4,
        "expected {}, got {}",
        expected,
        d
    );
}

