#[test]
fn test_get_hrtf_interpolated_weights_sum_to_one() {
    let sf = SofaFile {
        sample_rate: 48000.0,
        num_measurements: 3,
        ir_length: 2,
        positions: vec![
            SourcePosition::new(0.0, 0.0, 1.0),
            SourcePosition::new(30.0, 0.0, 1.0),
            SourcePosition::new(60.0, 0.0, 1.0),
        ],
        impulse_responses: vec![
            0.1, 0.2, 0.3, 0.4, // m0
            0.5, 0.6, 0.7, 0.8, // m1
            0.9, 1.0, 1.1, 1.2, // m2
        ],
        convention: "test".to_string(),
        data_sample_rate: Some(48000.0),
    };
    let query = SourcePosition::new(15.0, 0.0, 1.0);
    let h = sf.get_hrtf_interpolated(&query).unwrap();

    let nbrs = sf.find_three_nearest(&query);
    const EPS: f32 = 1e-4;
    let mut weights = [0.0f32; 3];
    let mut total = 0.0f32;
    for (i, (_, dist)) in nbrs.iter().enumerate() {
        let w = 1.0 / (*dist + EPS);
        weights[i] = w;
        total += w;
    }
    for w in weights.iter_mut() {
        *w /= total;
    }

    let expected_left: Vec<f32> = nbrs
        .iter()
        .zip(weights.iter())
        .map(|((idx, _), w)| {
            let (_, l, _) = sf.get_hrtf_slices(*idx).unwrap();
            l.iter().map(|s| s * *w).collect::<Vec<_>>()
        })
        .fold(vec![0.0f32; sf.ir_length], |mut acc, v| {
            for (a, s) in acc.iter_mut().zip(v.iter()) {
                *a += *s;
            }
            acc
        });
    let expected_right: Vec<f32> = nbrs
        .iter()
        .zip(weights.iter())
        .map(|((idx, _), w)| {
            let (_, _, r) = sf.get_hrtf_slices(*idx).unwrap();
            r.iter().map(|s| s * *w).collect::<Vec<_>>()
        })
        .fold(vec![0.0f32; sf.ir_length], |mut acc, v| {
            for (a, s) in acc.iter_mut().zip(v.iter()) {
                *a += *s;
            }
            acc
        });

    assert_eq!(h.ir_left.len(), sf.ir_length);
    assert_eq!(h.ir_right.len(), sf.ir_length);
    for (got, exp) in h.ir_left.iter().zip(expected_left.iter()) {
        assert!(
            (got - exp).abs() < 1e-5,
            "left IR mismatch: got {}, expected {}",
            got,
            exp
        );
    }
    for (got, exp) in h.ir_right.iter().zip(expected_right.iter()) {
        assert!(
            (got - exp).abs() < 1e-5,
            "right IR mismatch: got {}, expected {}",
            got,
            exp
        );
    }
}

