#[test]
fn test_validate_simple_free_field_hrtf_lengths() {
    let valid = || SimpleFreeFieldHrtf {
        real: &[1.0, 2.0, 3.0, 4.0],
        imag: &[0.1, 0.2, 0.3, 0.4],
        frequencies: &[100.0, 200.0],
        source_position: &[0.0, 0.0, 1.0],
        source_coords: CoordinateSystem::Spherical,
        receiver_position: &[0.0, 0.09, 0.0, 0.0, -0.09, 0.0],
        receiver_coords: CoordinateSystem::Cartesian,
        listener_position: None,
        title: None,
        measurements: 1,
        receivers: 2,
    };
    assert!(super::types::validate_simple_free_field_hrtf(&valid()).is_ok());

    let bad = SimpleFreeFieldHrtf {
        real: &[1.0, 2.0],
        ..valid()
    };
    assert!(matches!(
        super::types::validate_simple_free_field_hrtf(&bad),
        Err(SofaError::InvalidStructure(msg)) if msg.contains("Real length")
    ));

    let bad = SimpleFreeFieldHrtf {
        imag: &[0.1],
        ..valid()
    };
    assert!(matches!(
        super::types::validate_simple_free_field_hrtf(&bad),
        Err(SofaError::InvalidStructure(msg)) if msg.contains("Imag length")
    ));

    let bad = SimpleFreeFieldHrtf {
        source_position: &[0.0, 0.0],
        ..valid()
    };
    assert!(matches!(
        super::types::validate_simple_free_field_hrtf(&bad),
        Err(SofaError::InvalidStructure(msg)) if msg.contains("SourcePosition length")
    ));

    let bad = SimpleFreeFieldHrtf {
        receiver_position: &[0.0, 0.09, 0.0],
        ..valid()
    };
    assert!(matches!(
        super::types::validate_simple_free_field_hrtf(&bad),
        Err(SofaError::InvalidStructure(msg)) if msg.contains("ReceiverPosition length")
    ));
}

